/*
 * GreenLight Motion Engine — the sound library (PLANS/GREENLIGHT_MOTION_ENGINE_PLAN.md, Part 7).
 *
 * The owner's sounds (2026-10-17): 51 from the free Motion Design Pack and 28 generated for GreenLight on WaveSpeed
 * (picked in the Sound Analogs lab). The files live on the CDN (SOUND_CDN, an immutable version folder published by
 * motion-engine/scripts/upload-sounds.sh); the engine ships only this CATALOG (./soundLibrary.js, generated by
 * motion-engine/scripts/sound-catalog.mjs). A page gets a sound from its ASSETS (the CLI copies the files a project's
 * cues use into assets/sounds/); GreenLight Dash copies them onto the board through its backend (appImport.js).
 *
 *   SOUNDS[id] → { id, label, category, use, origin, file, duration, sync, level }
 *     sync   the sound's loudest 10 ms (a click's contact, a whoosh's pass, a hit) — what a cue lines up with its event
 *     level  its peak in dBFS (a few files peak above 0: a cue gives every sound CUE_HEADROOM_DB of headroom)
 *   soundRef(id)    → 'asset:sounds/<file>' (what a cue's audio clip plays in a page)
 *   soundUrl(id)    → the file on the CDN
 *   soundByRef(ref) → the sound a page ref names, or null
 */
import { LIBRARY, SOUND_CDN } from './soundLibrary.js';

export { SOUND_CDN };
export const SOUNDS = Object.fromEntries(LIBRARY.map((s) => [s.id, s]));
export const SOUND_NAMES = LIBRARY.map((s) => s.id);
export const SOUND_CATEGORIES = [...new Set(LIBRARY.map((s) => s.category))];
// the loudest a cue lets a sound peak (dBFS): a library file that peaks hotter is turned down to this
export const CUE_HEADROOM_DB = -1;

export const soundRef = (id) => (SOUNDS[id] ? `asset:sounds/${SOUNDS[id].file}` : null);
export const soundUrl = (id) => (SOUNDS[id] ? `${SOUND_CDN}/${SOUNDS[id].file}` : null);
export const soundByRef = (ref) => LIBRARY.find((s) => `asset:sounds/${s.file}` === ref) || null;
